from pathlib import Path
import re

SRC=Path('market-navigator-turn18-pre-ship.html')
DST=Path('market-navigator-turn19-pre-ship.html')
s=SRC.read_text()


def must(old,new,count=1):
    global s
    n=s.count(old)
    if n < count:
        raise SystemExit(f'missing replacement ({n}<{count}): {old[:100]!r}')
    s=s.replace(old,new,count)

# Version / owner-visible naming.
s=s.replace('Market Navigator · Turn 18','Market Navigator · Turn 19')
s=s.replace('TURN 18 PRE-SHIP','TURN 19 PRE-SHIP')
s=s.replace('TURN18_DISPLAY_DENSITY','TURN19_DISPLAY_DENSITY')
must('<div class="crumb" id="crumb">ENVIRONMENT</div>','<div class="crumb" id="crumb">ENV</div>')
must('id="nowCrumb" title="ENVIRONMENT" aria-label="ENVIRONMENT"','id="nowCrumb" title="ENV" aria-label="ENV"')

# Chrome geometry: center and More own fixed geometry; breadcrumb can never displace them.
must('.chartChromeRow{height:44px;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) max-content minmax(0,1fr);align-items:center;gap:8px;padding:5px 9px;border-bottom:1px solid #1c3449}',
     '.chartChromeRow{height:44px;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) max-content 34px;align-items:center;gap:8px;padding:5px 9px;border-bottom:1px solid #1c3449}')
must('.chromeCrumb{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;font-weight:900}.chromeCrumb .crumbBtn{font-size:11px}.chromeCrumbText{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chromeCenter{justify-self:center;min-width:0}.chromeRight{justify-self:end;display:flex;align-items:center}',
     '.chromeCrumb{min-width:0;overflow:hidden;white-space:nowrap;font-size:11px;font-weight:900}.chromeCrumb .crumbBtn{font-size:11px}.chromeCrumbText{display:flex;align-items:center;min-width:0;overflow:hidden;white-space:nowrap}.crumbLeaf{display:inline-block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chromeCenter{justify-self:center;min-width:0}.chromeRight{justify-self:end;display:flex;align-items:center;justify-content:flex-end;width:34px;min-width:34px}')

# Compact optional info popovers. Replace the prior card geometry with deliberate header/body/footer layout.
old_info=re.compile(r'\.info\{left:auto!important;right:18px!important;top:86px!important;.*?\.legendSwatch\{width:34px;height:14px;display:block;overflow:visible;flex:none\}',re.S)
m=old_info.search(s)
if not m: raise SystemExit('missing Turn18 info CSS block')
new_info='''.info{left:auto!important;right:12px!important;top:84px!important;bottom:auto!important;transform:none!important;width:min(258px,calc(100% - 18px))!important;max-height:196px!important;overflow:hidden!important;z-index:8!important;padding:0!important;background:#fff!important;color:#111!important;border-color:#c9c9c9!important;box-shadow:0 6px 22px #0005!important;pointer-events:none!important}.infoHead{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:5px;padding:5px 6px;border-bottom:1px solid #ddd}.infoTitle{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;font-weight:900}.infoBody{display:grid;gap:2px;padding:5px 7px;font-size:8.5px;line-height:1.22}.infoBody b{display:inline-block;min-width:48px}.infoFoot{display:flex;justify-content:space-between;align-items:center;padding:4px 6px;border-top:1px solid #ddd}.info .infoHead,.info .infoFoot,.info button,.info a{pointer-events:auto!important}.info .btn{background:#fff!important;color:#111!important;border-color:#aaa!important;padding:3px 6px!important;font-size:9px!important}.infoHealth{border:0;background:transparent;color:#174d75;text-decoration:underline;padding:0;font:inherit;cursor:pointer}.seriesInfo19{position:absolute!important;right:12px!important;top:84px!important;left:auto!important;width:min(258px,calc(100% - 18px))!important;max-height:196px!important;padding:0!important;background:#fff!important;color:#111!important;border:1px solid #c9c9c9!important;border-radius:9px!important;box-shadow:0 6px 22px #0005!important;overflow:hidden!important;z-index:24!important}.seriesInfo19 .btn{background:#fff!important;color:#111!important;border-color:#aaa!important;padding:3px 6px!important;font-size:9px!important}.legendSwatch{width:34px;height:14px;display:block;overflow:visible;flex:none}'''
s=s[:m.start()]+new_info+s[m.end():]
# Replace mobile info override.
s=re.sub(r'@media\(max-width:700px\)\{\.info\{right:6px!important;top:84px!important;width:min\(286px,calc\(100% - 12px\)\)!important;max-height:205px!important;padding:7px!important\}\.info \.kv\{grid-template-columns:64px minmax\(0,1fr\)!important;font-size:8px!important\}',
         '@media(max-width:700px){.info,.seriesInfo19{right:5px!important;top:82px!important;width:min(248px,calc(100% - 10px))!important;max-height:190px!important}',s,count=1)
# Tooltip becomes pinned and explicitly dismissible.
must('.tip{position:absolute;display:none;z-index:5;pointer-events:none;background:#06101ef2;border:1px solid #55718e;border-radius:7px;padding:6px 8px;font-size:10px;box-shadow:0 8px 24px #0008;white-space:nowrap}',
     '.tip{position:absolute;display:none;z-index:25;pointer-events:auto;background:#06101ef2;border:1px solid #55718e;border-radius:7px;padding:6px 24px 6px 8px;font-size:10px;box-shadow:0 8px 24px #0008;white-space:nowrap}.tipClose{position:absolute;right:3px;top:2px;border:0;background:transparent;color:#fff;font-weight:900;line-height:1;cursor:pointer;padding:2px 4px}')

# Derived indices are explicit measurement families when opened standalone or mixed with comparisons.
must("function measurementFamily(id){let u=String(unit(id)||'').trim().toLowerCase().replace(/\\s+/g,' ');",
     "function measurementFamily(id){if(IDX.includes(id))return'derived-index:'+id;let u=String(unit(id)||'').trim().toLowerCase().replace(/\\s+/g,' ');")

# Replace breadcrumb block and representation footer helper.
