crumb_block=r'''function pluralComponents(n){return n===1?'Component':'Components'}
function nowBreadcrumbText(){return S.level===1?'ENV':`ENV / ${AB[S.index]}`}
function renderNowCrumb(){let c=$('nowCrumb');if(!c)return;let full=nowBreadcrumbText();c.title=full;c.setAttribute('aria-label',full);if(S.level===1)c.innerHTML='<span class="chromeCrumbText"><span>ENV</span></span>';else{c.innerHTML=`<span class="chromeCrumbText"><button class="crumbBtn" id="crumbEnvironment">ENV</button><span class="crumbSep"> / </span><span>${AB[S.index]}</span></span>`;let b=$('crumbEnvironment');if(b)b.onclick=()=>{S.level=1;S.index=null;S.priorV2=null;$('info').classList.add('hidden');$('nowTip').style.display='none';S.nowFocus=null;renderV1()}}}
function renderAnalysisCrumb(){let c=$('analysisCrumb');if(!c)return;let root=displayLabel(S.analysisRoot||S.analysisSeries[0]||'COMPONENT'),extra=Math.max(0,S.analysisSeries.length-1),suffix=extra?` + ${extra} ${pluralComponents(extra)}`:'',leaf=root+suffix,fromExplore=String(S.lineage||'').toUpperCase().includes('EXPLORE'),full=fromExplore?`EXPLORE / ${leaf}`:`ENV / ${AB[S.index]||''} / ${leaf}`;c.title=full;c.setAttribute('aria-label',full);if(fromExplore)c.innerHTML=`<span class="chromeCrumbText"><button class="crumbBtn" id="crumbExplore">EXPLORE</button><span class="crumbSep"> / </span><span class="crumbLeaf" title="${esc(leaf)}" aria-label="${esc(leaf)}">${esc(leaf)}</span></span>`;else c.innerHTML=`<span class="chromeCrumbText"><button class="crumbBtn" id="crumbComponentEnvironment">ENV</button><span class="crumbSep"> / </span><button class="crumbBtn" id="crumbComponentIndex">${AB[S.index]||''}</button><span class="crumbSep"> / </span><span class="crumbLeaf" title="${esc(leaf)}" aria-label="${esc(leaf)}">${esc(leaf)}</span></span>`;let ce=$('crumbComponentEnvironment'),ci=$('crumbComponentIndex'),cx=$('crumbExplore');if(ce)ce.onclick=()=>{$('analysisModal').classList.add('hidden');S.level=1;S.index=null;S.analysisRepresentation=null;S.analysisFocus=null;$('info').classList.add('hidden');renderV1()};if(ci)ci.onclick=()=>$('closeAnalysis').click();if(cx)cx.onclick=()=>{$('analysisModal').classList.add('hidden');S.analysisRepresentation=null;S.analysisFocus=null;nav('explore')}}
function footerOptions(mode,families,derivedOnly=false){let one=families===1&&!derivedOnly,two=families===2;return`<option value="native" ${mode==='native'?'selected':''} ${one?'':'disabled'}>Native Y1</option><option value="dual" ${mode==='dual'?'selected':''} ${two?'':'disabled'}>Native Y1 + Y2</option><option value="indexed" ${mode==='indexed'?'selected':''}>Indexed 100</option>`}
function setNowFooter(w){$('nowMeta').innerHTML=`<span>TURN 19 PRE-SHIP</span><span class="footerSep">|</span><span>${w.startLabel} → ${w.endLabel}</span><span class="footerSep">|</span><select id="nowRepresentation" aria-label="Chart representation"><option selected>Indexed 100</option><option disabled>Native Y1</option><option disabled>Native Y1 + Y2</option></select>`}
function setAnalysisFooter(w,mode,families,derivedOnly=false){$('analysisMeta').innerHTML=`<span>TURN 19 PRE-SHIP</span><span class="footerSep">|</span><span>${w.startLabel} → ${w.endLabel}</span><span class="footerSep">|</span><select id="analysisRepresentation" aria-label="Chart representation">${footerOptions(mode,families,derivedOnly)}</select>`;$('analysisRepresentation').onchange=e=>{if(derivedOnly&&e.target.value!=='indexed'){e.target.value='indexed';return}S.analysisRepresentation=e.target.value;renderAnalysis()}}
'''
s=s[:m.start()]+crumb_block+s[m.end():]

# Point inspection: selection never auto-opens info; crosshair readout pins until explicit close/context change.
old="if(allowSelect&&hit.near.dist<24){sel=hit.near.z;setActive(sel.id,true);syncActive();if(which==='now'&&S.level!==1){if(IDX.includes(sel.id))$('info').classList.add('hidden');else{S.priorV2.component=sel.id;componentCard(sel.id)}}}"
new="if(allowSelect&&hit.near.dist<24){sel=hit.near.z;setActive(sel.id,true);syncActive();if(which==='now'&&S.level!==1){if(S.priorV2)S.priorV2.component=sel.id===S.index?null:sel.id;$('info').classList.add('hidden')}if(which==='analysis')$('seriesAbout').classList.add('hidden')}"
must(old,new)
old_tip="tip.innerHTML=`<strong>${esc(sel.label)}</strong><br>${full(q.sourceT||q.t)} · ${valueLine}`;tip.style.display='block';tip.style.left=Math.min(model.W-180,Math.max(6,xx+8))+'px';tip.style.top=Math.max(6,yy-48)+'px'}c.onpointermove=e=>{if(e.pointerType!=='touch')inspect(e,false)};c.onpointerdown=e=>inspect(e,true);c.onpointerleave=()=>{tip.style.display='none';model=paint()};c.ontouchstart=e=>{e.preventDefault();inspect(e,true)};c.ontouchmove=e=>{e.preventDefault();inspect(e,false)}}"
new_tip="tip.innerHTML=`<button class=\"tipClose\" data-tip-close aria-label=\"Close inspection\">×</button><strong>${esc(sel.label)}</strong><br>${full(q.sourceT||q.t)} · ${valueLine}`;tip.style.display='block';tip.style.left=Math.min(model.W-180,Math.max(6,xx+8))+'px';tip.style.top=Math.max(6,yy-48)+'px';let tc=tip.querySelector('[data-tip-close]');if(tc)tc.onclick=e=>{e.stopPropagation();tip.style.display='none';model=paint()}}c.onpointermove=e=>{if(e.pointerType!=='touch')inspect(e,false)};c.onpointerdown=e=>inspect(e,true);c.onpointerleave=()=>{};c.ontouchstart=e=>{e.preventDefault();inspect(e,true)};c.ontouchmove=e=>{e.preventDefault();inspect(e,false)}}"
