analysis_block=r'''async function openAnalysis(ids,lineage,root){S.analysisRoot=root||ids[0];S.analysisSeries=[...ids];S.analysisActive=S.analysisRoot;S.analysisFocus=S.analysisRoot;S.analysisRepresentation=null;S.lineage=lineage;$('analysisTip').style.display='none';$('analysisModal').classList.remove('hidden');await renderAnalysis()}
async function renderAnalysis(){let renderSeq=++S.analysisRenderSeq;makeHz($('analysisHz'),h=>{S.h=h;S.analysisRepresentation=null;$('analysisTip').style.display='none';renderAnalysis();wireNowHz()});let w=windowFor(),colors=chartColors(S.analysisSeries),loaded=[];for(let id of S.analysisSeries){if(IDX.includes(id)){let rec=S.derived.indices[id]?.horizons?.[S.h];if(rec)loaded.push({id,label:AB[id],full:S.def.indices[id]?.name||AB[id],unit:'Index',color:colors[id],renderType:'line',derived:true,curve:rec.curve||[]});continue}try{loaded.push({id,label:displayLabel(id),full:name(id),unit:unit(id),color:colors[id],renderType:'line',s:await getSeries(id)})}catch{}}let plan=axisPlan(loaded.map(x=>x.id)),families=plan.kinds.length,derivedOnly=loaded.length>0&&loaded.every(x=>x.derived),canonical=derivedOnly?'indexed':plan.mode,mode=S.analysisRepresentation||canonical;if(derivedOnly)mode='indexed';if(mode==='native'&&families!==1)mode=canonical;if(mode==='dual'&&families!==2)mode=canonical;if(!['native','dual','indexed'].includes(mode))mode=canonical;S.analysisRepresentation=mode;let sets=loaded.map(z=>{let a;if(z.derived)a=(z.curve||[]).map(p=>({t:+p.t,v:+p.v,idx:+p.v,raw:+p.v,sourceT:+p.t}));else a=mode==='indexed'?indexed(z.s,w,1):nativeIndexed(z.s,w);return{id:z.id,label:z.label,full:z.full,unit:z.unit,color:z.color,renderType:'line',axis:mode==='dual'?(plan.map[z.id]||0):0,axisLabel:z.derived?'Index':(unitKind(z.id)==='percent'?'Percent':unitKind(z.id)==='money'?'$ / USD':z.unit),a}});if(renderSeq!==S.analysisRenderSeq)return;let reps=plan.kinds.map(k=>loaded.find(z=>measurementFamily(z.id)===k)).filter(Boolean);$('analysisTitle').textContent=`COMPONENT · ${displayLabel(S.analysisRoot)}`;$('axisBadge').textContent=mode==='dual'?`Y1 ${reps[0]?unitGlyph(reps[0].id):''} · Y2 ${reps[1]?unitGlyph(reps[1].id):''}`:mode==='indexed'?'Indexed 100':'Native Y1';renderAnalysisCrumb();setAnalysisFooter(w,mode,families,derivedOnly);$('seriesBar').innerHTML=loaded.map(z=>`<button class="chip ${z.id===S.analysisActive?'on':''}" data-id="${z.id}" data-color-slot="${colorSlot(z.id)}" style="border-color:${z.color};box-shadow:inset 3px 0 ${z.color}"><span class="seriesLegend">${legendSample(z)}${esc(z.label)}<span class="seriesX" data-rm="${z.id}">×</span></span></button>`).join('')+`<button class="btn" id="addSeries" ${loaded.length>=10?'disabled aria-disabled="true" title="Ten-series chart limit"':''}>Add</button>`;wireLegend19($('seriesBar'),(id,e)=>{if(e.target.closest('[data-rm]'))return;S.analysisActive=id;S.analysisFocus=id;$('analysisTip').style.display='none';$('seriesAbout').classList.add('hidden');renderAnalysis()},'analysis');$('seriesBar').querySelectorAll('[data-rm]').forEach(x=>x.onclick=e=>{e.stopPropagation();if(S.analysisSeries.length<=1)return;let id=x.dataset.rm;S.analysisSeries=S.analysisSeries.filter(v=>v!==id);if(S.analysisRoot===id)S.analysisRoot=S.analysisSeries[0];if(S.analysisActive===id)S.analysisActive=S.analysisRoot;S.analysisRepresentation=null;$('analysisTip').style.display='none';renderAnalysis()});$('addSeries').onclick=()=>{if(S.analysisSeries.length>=10)return;renderPicker();$('seriesPicker').classList.remove('hidden')};$('moreBtn').onclick=()=>$('moreMenu').classList.toggle('hidden');$('moreAI').onclick=()=>{$('moreMenu').classList.add('hidden');startAI()};$('moreData').onclick=async()=>{$('moreMenu').classList.add('hidden');await openData17(S.analysisChartState)};$('morePrint').onclick=()=>{$('moreMenu').classList.add('hidden');window.print()};$('moreMarkdown').onclick=()=>{$('moreMenu').classList.add('hidden');downloadAnalysisState('md')};$('moreCsv').onclick=()=>{$('moreMenu').classList.add('hidden');downloadAnalysisState('csv')};$('moreJson').onclick=()=>{$('moreMenu').classList.add('hidden');downloadAnalysisState('json')};$('analysisEvidence').innerHTML=loaded.map(z=>{let c=z.derived?{}:cat(z.id),h=z.derived?{classification:'derived'}:health(z.id);return`<div class="row"><strong>${esc(z.label)} · ${esc(z.full)}</strong><span class="rowMeta">${esc(z.derived?'derived':(c.provider||''))} · ${esc(z.unit||'—')} · ${esc(h.classification||'unknown')}</span>${!z.derived&&c.source_reference_url?`<br><a href="${esc(c.source_reference_url)}" target="_blank" rel="noopener">Source</a>`:''}</div>`}).join('');captureAnalysisState17(sets,w,mode);draw('analysis',sets,w,mode)}
$('closeAnalysis').onclick='''
s=s[:m.start()]+analysis_block+s[m.end():]

# Returning up never resurrects the old automatic information card.
old_close="if(S.lineage==='NOW'&&S.priorV2){S.level=2;S.index=S.priorV2.index;S.h=S.priorV2.h;S.nowActive=S.priorV2.component||S.index;wireNowHz();renderV2();if(S.priorV2.component)componentCard(S.priorV2.component)}"
new_close="if(S.lineage==='NOW'&&S.priorV2){S.level=2;S.index=S.priorV2.index;S.h=S.priorV2.h;S.nowActive=S.priorV2.component||S.index;S.nowFocus=S.priorV2.component||null;wireNowHz();$('info').classList.add('hidden');renderV2()}"
must(old_close,new_close)

# No visible historical root token remains in current chart UI strings.
s=s.replace("$('nowTitle').textContent='ENVIRONMENT'","$('nowTitle').textContent='ENV'")

# Sanity checks for source-level implementation.
required=[
 'TURN 19 PRE-SHIP','grid-template-columns:minmax(0,1fr) max-content 34px','function wireLegend19',
 "S.level===1?'ENV':`ENV / ${AB[S.index]}`",'function showInfo19','data-info-health',
 "c.onpointerleave=()=>{}",'tipClose','derivedOnly',"loaded.every(x=>x.derived)",
 "wireLegend19($('legend'),async id=>", "wireLegend19($('seriesBar')"
]
for q in required:
    if q not in s: raise SystemExit('missing Turn19 marker: '+q)
if 'TURN 18 PRE-SHIP' in s: raise SystemExit('stale Turn18 build label')
DST.write_text(s)
print('TURN 19 BUILD: PASS')
